create extension if not exists "uuid-ossp";
create type public.user_role as enum ('customer', 'admin');
create type public.order_status as enum ('pending', 'confirmed', 'processing', 'shipped', 'delivered', 'cancelled', 'returned');
create type public.payment_state as enum ('pending', 'paid', 'failed', 'refunded');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, email text, phone text, role public.user_role not null default 'customer', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.categories (id uuid primary key default uuid_generate_v4(), name text not null, slug text unique not null, description text, image_url text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.products (id uuid primary key default uuid_generate_v4(), name text not null, slug text unique not null, description text, category_id uuid references public.categories(id) on delete set null, sku text unique not null, supplier_sku text, cost_price numeric(12,2), price numeric(12,2) not null check (price >= 0), compare_at_price numeric(12,2), stock_quantity integer not null default 0 check (stock_quantity >= 0), is_active boolean not null default true, is_featured boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.product_images (id uuid primary key default uuid_generate_v4(), product_id uuid not null references public.products(id) on delete cascade, image_url text not null, alt_text text, sort_order integer not null default 0, created_at timestamptz not null default now());
create table public.product_variants (id uuid primary key default uuid_generate_v4(), product_id uuid not null references public.products(id) on delete cascade, name text not null, value text not null, sku text, price numeric(12,2), stock_quantity integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.orders (id uuid primary key default uuid_generate_v4(), order_number text unique not null, user_id uuid references public.profiles(id) on delete set null, customer_name text not null, customer_email text not null, customer_phone text not null, shipping_address text not null, city text not null, province text not null, postal_code text, notes text, subtotal numeric(12,2) not null, shipping_fee numeric(12,2) not null default 200, total numeric(12,2) not null, payment_method text not null default 'cod', payment_status public.payment_state not null default 'pending', order_status public.order_status not null default 'pending', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.order_items (id uuid primary key default uuid_generate_v4(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid references public.products(id) on delete set null, product_name text not null, variant text, quantity integer not null check (quantity > 0), unit_price numeric(12,2) not null, total_price numeric(12,2) not null, created_at timestamptz not null default now());
create table public.reviews (id uuid primary key default uuid_generate_v4(), product_id uuid not null references public.products(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade, rating integer not null check (rating between 1 and 5), title text, comment text, is_approved boolean not null default false, created_at timestamptz not null default now());
create table public.wishlist (id uuid primary key default uuid_generate_v4(), user_id uuid not null references public.profiles(id) on delete cascade, product_id uuid not null references public.products(id) on delete cascade, created_at timestamptz not null default now(), unique(user_id, product_id));
create index products_category_idx on public.products(category_id); create index orders_user_idx on public.orders(user_id); create index order_items_order_idx on public.order_items(order_id);
create or replace function public.decrement_product_stock(product_id uuid, amount integer) returns void language plpgsql security definer set search_path = public as $$ begin update public.products set stock_quantity = stock_quantity - amount, updated_at = now() where id = product_id and is_active = true and stock_quantity >= amount; if not found then raise exception 'insufficient stock'; end if; end; $$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.profiles where id = auth.uid() and role = 'admin'); $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles (id, email, full_name) values (new.id, new.email, new.raw_user_meta_data->>'full_name'); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security; alter table public.categories enable row level security; alter table public.products enable row level security; alter table public.product_images enable row level security; alter table public.product_variants enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.reviews enable row level security; alter table public.wishlist enable row level security;
create policy "public read active categories" on public.categories for select using (is_active or public.is_admin()); create policy "public read active products" on public.products for select using (is_active or public.is_admin()); create policy "public read product images" on public.product_images for select using (exists (select 1 from public.products p where p.id = product_id and (p.is_active or public.is_admin()))); create policy "public read variants" on public.product_variants for select using (exists (select 1 from public.products p where p.id = product_id and (p.is_active or public.is_admin()))); create policy "users read own profile" on public.profiles for select using (id = auth.uid() or public.is_admin()); create policy "users update own profile" on public.profiles for update using (id = auth.uid()) with check (id = auth.uid()); create policy "users read own orders" on public.orders for select using (user_id = auth.uid() or public.is_admin()); create policy "users read own items" on public.order_items for select using (exists (select 1 from public.orders o where o.id = order_id and (o.user_id = auth.uid() or public.is_admin()))); create policy "public read approved reviews" on public.reviews for select using (is_approved or user_id = auth.uid() or public.is_admin()); create policy "users manage own wishlist" on public.wishlist for all using (user_id = auth.uid() or public.is_admin()) with check (user_id = auth.uid() or public.is_admin());
create policy "admins manage catalog" on public.categories for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage products" on public.products for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage images" on public.product_images for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage variants" on public.product_variants for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage orders" on public.orders for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage items" on public.order_items for all using (public.is_admin()) with check (public.is_admin()); create policy "admins manage reviews" on public.reviews for all using (public.is_admin()) with check (public.is_admin());
